const preference=window.matchMedia('(prefers-reduced-motion: reduce)');
let paused=false;try{paused=localStorage.getItem('despensa-motion')==='off'}catch{}
const animations=new Set();
function setMotion(){document.documentElement.toggleAttribute('data-motion-off',paused||preference.matches);document.querySelectorAll('.motion-control').forEach(b=>{b.textContent=paused?'Activar animaciones':'Pausar animaciones';b.setAttribute('aria-pressed',String(paused))});if(paused||preference.matches)animations.forEach(a=>a.finish())}
setMotion();preference.addEventListener('change',setMotion);
document.querySelectorAll('.motion-control').forEach(b=>b.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('despensa-motion',paused?'off':'on')}catch{}setMotion()}));
// Finite entrances, never hide content while waiting for script or for the observer.
if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>{entries.forEach(({isIntersecting,target})=>{if(!isIntersecting)return;if(!paused&&!preference.matches){const a=target.animate([{transform:'translateY(24px)',opacity:.65},{transform:'translateY(0)',opacity:1}],{duration:750,easing:'cubic-bezier(.2,.8,.2,1)',fill:'none'});animations.add(a);a.finished.then(()=>animations.delete(a)).catch(()=>{})}io.unobserve(target)})},{threshold:.12});document.querySelectorAll('[data-enter],.review-card,.menu-row').forEach(el=>io.observe(el))}
const search=document.querySelector('#dish-search');
if(search){const clean=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();search.addEventListener('input',()=>{const value=clean(search.value.trim());let count=0;document.querySelectorAll('[data-menu-category]').forEach(section=>{let visible=0;section.querySelectorAll('.menu-row').forEach(row=>{row.hidden=!clean(row.dataset.name).includes(value);if(!row.hidden){visible++;count++}});section.hidden=visible===0});const status=document.querySelector('.search-status');status.textContent=value?(count?`${count} ${count===1?'resultado':'resultados'} para «${search.value.trim()}».`:'No hay platos con ese nombre. Prueba otra búsqueda.') :'';document.querySelector('.category-nav').hidden=!!value});}
document.querySelector('.print-menu')?.addEventListener('click',()=>{if(search?.value){search.value='';search.dispatchEvent(new Event('input'))}window.print()});
// Business hours are evaluated in mainland Spain, not the visitor's timezone.
const output=document.querySelector('[data-hours-status]');if(output){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const minute=Number(parts.hour)*60+Number(parts.minute);const day=parts.weekday;let text='Hoy cerrado';if(['Wed','Thu','Fri','Sat'].includes(day)){text=minute>=780&&minute<990?'Abierto · hasta las 16:30':minute>=1200?'Abierto · hasta las 00:00':minute<780?'Hoy abrimos a las 13:00':'Hoy abrimos a las 20:00'}if(day==='Sun')text=minute>=810&&minute<990?'Abierto · hasta las 16:30':minute<810?'Hoy abrimos a las 13:30':'Hoy cerrado';output.textContent=text}
// Complete keyboard loop for the mobile navigation sheet.
const nav=document.querySelector('header.nav');nav?.addEventListener('keydown',e=>{if(e.key!=='Tab'||!nav.classList.contains('is-open'))return;const focusables=[...nav.querySelectorAll('a,button')].filter(el=>el.getClientRects().length);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
